t = V["exclusions_total"]
A(f"\\midrule All & {t['sampled']} & {t['excl_e3']} & {t['excl_s']} & {t['included']} & {t['median_G_e3']:.3f} & {t['median_G_s']:.3f} & {t['median_ndf_e3']:.2f} & {t['median_ndf_s']:.2f}\\\\\\bottomrule\\end{{tabular}}}}")
cc = V["complete_case"]
A("\n\nComplete-case selection: rows with any missing value were " + ", ".join(f"{LAB[d]} {v['rows_with_missing']}/{v['rows']}" for d, v in cc.items() if v["rows_with_missing"]) +
  f"; all other datasets had none. Wilcoxon test of $G$ (HE vs S*), all sampled patients: {pe(t['wilcoxon_G_p'])}. Share of included patients with lower NDF for HE: {100*t['share_e3_lower']:.0f}\\%.")
sh = V["shrinkage_similarG"]["pooled"]
A(f"\n\n\\textbf{{Similar-gap check.}} Restricting to patients whose gaps differ by less than a factor 1.5 ({V['shrinkage_similarG']['n_patients']} patients): pooled $\\Delta$NDF {mn(sh['pooled'])}, DL 95\\% CI {c2(sh['ci_low'], sh['ci_high'])}, HKSJ {c2(*sh['hksj_ci'])}.")
# S3 meta
thr = V2["threshold"]
