    A(f"{nm[a1]} $-$ {nm[b1]} & {mn(a['pooled'])} & {c2(a['ci_low'], a['ci_high'])} & {c2(*a['hksj_ci'])} & {fp(a['p'])} & {mn(b['pooled'])}\\\\")
